import { defineConfig } from 'vite-plus';

import { createFmtConfig } from '@repo/vite-configs/fmt';

const fmtConfig = createFmtConfig({
  // `reports/sonar/` is machine-generated by `scripts/sonar-report.mjs` with
  // `JSON.stringify(…, null, 2)` — the same stable convention the other report
  // generators use. Sonar findings carry populated short arrays (e.g. issue
  // `tags`) that Oxfmt collapses onto one line, so the generator and formatter
  // would fight and churn the file on every run. Keep Oxfmt out of it; the
  // generator's output is the canonical, deterministic format.
  ignorePatterns: [
    '.react-router/',
    'build/',
    'miscelanious/',
    'reports/sonar/',
  ],
});

export default defineConfig({
  fmt: fmtConfig,
  lint: {
    // `correctness` is Oxlint's bug category — `no-debugger`, `no-dupe-keys`,
    // `no-self-compare`. It defaults to WARN, and a warning does not fail
    // anything: `vp lint .` and `vp check` both exit 0 while printing "Found 0
    // errors and 1 warning". Until this line, a `debugger` statement could be
    // committed, pass every gate, and ship.
    //
    // Oxlint reads THIS block and only this one. The per-workspace `lint:`
    // entries pointing at `@repo/vite-configs/*-lint` do not reach it — proven
    // by setting a rule to `error` in the shared config a workspace consumes
    // and watching the violation still report as a warning, from the workspace
    // and from the root, under `vp lint` and under `vp check` alike. So any
    // severity that is meant to bite has to be set here. See #318.
    //
    // Measured before landing: enabling `correctness` at error costs ZERO
    // findings across all 3178 files. The other categories are not free —
    // perf 30, suspicious 742, restriction 7270, pedantic 7738, style 12760 —
    // and each needs its own decision rather than a blanket flip.
    categories: { correctness: 'error' },
    options: { typeAware: true, typeCheck: true },
  },
  run: {
    tasks: {
      build: {
        // Orchestrator — individual package tasks handle their own caching
        cache: false,
        command: 'vp run -r build',
      },
    },
  },
  staged: {
    '*': 'vp check --fix',
    // `vp check` is fmt + Oxlint + tsgolint and knows nothing about Biome, so
    // without this entry the Biome gate would only ever fail in CI — after the
    // commit it was supposed to block. Check-only on purpose: unlike the
    // `--fix` above, a Biome autofix here could rewrite a staged file after it
    // was reviewed, so a violation fails the commit and `vp run lint:biome`
    // applies the fix deliberately.
    '*.{ts,tsx,mjs,cjs}': 'biome lint --no-errors-on-unmatched',
  },
});
